// ❌ OLD: Writing manual validation checks inside controller methods.
// Susceptible to mass-assignment attacks (e.g. user injecting 'isAdmin: true').
import { Controller, Post, Body, BadRequestException } from '@nestjs/common';

@Controller('users')
export class UsersController {
  @Post()
  create(@Body() body: any) {
    if (!body.email || !body.email.includes('@')) {
      throw new BadRequestException('Invalid email');
    }
    if (typeof body.age !== 'number' || body.age < 18) {
      throw new BadRequestException('Age must be at least 18');
    }
    return { success: true };
  }
}

import { Controller, Post, Body, ValidationPipe, UsePipes } from '@nestjs/common';
import { IsEmail, IsInt, Min, IsString } from 'class-validator';
import { Type } from 'class-transformer';

export class CreateUserDto {
  @IsEmail()
  email: string;

  @IsInt()
  @Min(18)
  @Type(() => Number)
  age: number;
}

@Controller('users')
export class UsersController {
  @Post()
  @UsePipes(new ValidationPipe({ whitelist: true, forbidNonWhitelisted: true, transform: true }))
  create(@Body() createUserDto: CreateUserDto) {
    // ✅ Clean, validated, type-safe, and un-declared properties are stripped!
    return { user: createUserDto };
  }
}
